#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=12

# Run it on your laptop, from anywhere in the repo. The values go to host/.env here first,
# and stage 9 copies the file to the VM. host/.env is in .gitignore.
HOST_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
ENV_FILE="$HOST_DIR/.env"
REPO_URL="https://github.com/imranur-rahman/dependency-update-metrics.git"
WEBAPP_ORIGIN="https://imranur-rahman.github.io"
if [[ ! -f "$ENV_FILE" ]]; then
  (umask 077 && cp "$HOST_DIR/.env.example" "$ENV_FILE")
fi

banner "Deploy the Host to Google Compute Engine (ticket #15, ADR 0002)"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: the project and the budget alert"
say "The Host runs on an e2-standard-2 VM (about \$55 a month), paid by the research credit."
warn "Set the budget alert before you make the VM. When the credit ends, Google bills the card."
open_url "https://console.cloud.google.com/projectcreate"
step "Make a project (for example dependency-metrics), or pick the project of the credit."
step "Check that the billing account of the project holds the credit (Billing > Credits)."
open_url "https://console.cloud.google.com/billing/budgets"
step "Click Create budget. Scope: the project. Amount: \$60 a month."
step "Keep the alerts at 50%, 90%, and 100% of the budget, with e-mail to the billing admins."
open_url "https://console.cloud.google.com/apis/library/compute.googleapis.com"
step "Click Enable for the Compute Engine API."
pause "Press Enter when the budget is saved and the API is on."

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: the VM"
open_url "https://console.cloud.google.com/compute/instancesAdd"
step "Region: us-east1 (South Carolina). Zone: any."
step "Machine configuration: E2 > e2-standard-2 (2 vCPU, 8 GB memory)."
step "VM provisioning model: Standard. Do not use Spot, because Google can stop a Spot VM."
step "OS and storage: Ubuntu 24.04 LTS (x86/64), Balanced persistent disk, 50 GB."
step "Networking: tick 'Allow HTTP traffic' and 'Allow HTTPS traffic'."
step "Security > Manage access: add your public key (for example ~/.ssh/id_ed25519.pub)."
step "Click Create."
ask DM_VM_USER "SSH user on the VM (the name that the console shows next to your key):"
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: a static IP address"
say "A static address keeps the IP of the VM after a stop, so DuckDNS and HTTPS stay valid."
say "It costs the same as the address that the VM already uses."
open_url "https://console.cloud.google.com/networking/addresses/list"
step "Find the External IP of the VM. Click the three dots, then 'Promote to static IP address'."
step "Name: dmhost. Click Reserve."
ask DM_VM_IP "Paste the static IP of the VM:"
note "The wizard keeps the IP only for this run. It does not write it to a file."
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "VM: Docker, firewall, swap off, repo"
say "This stage connects to ${DM_VM_USER}@${DM_VM_IP} with SSH and runs host/vm-setup.sh."
say "The script installs Docker and the cron jobs of the disk alert and the weekly maintenance."
ask DM_DEPLOY_BRANCH "Branch to deploy (Enter for main):" || true
DM_DEPLOY_BRANCH="${DM_DEPLOY_BRANCH:-main}"
if confirm "Run the setup on the VM now?"; then
  # shellcheck disable=SC2029 # the variables expand here, on purpose
  ssh "${DM_VM_USER}@${DM_VM_IP}" \
    "set -e; [ -d dependency-update-metrics ] || git clone '${REPO_URL}'; \
     cd dependency-update-metrics && git checkout '${DM_DEPLOY_BRANCH}' && git pull --ff-only \
     && bash host/vm-setup.sh"
else
  SKIPPED+=("VM setup: ssh ${DM_VM_USER}@${DM_VM_IP}, clone the repo, run bash host/vm-setup.sh")
fi
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "DuckDNS: the subdomain and the token"
open_url "https://www.duckdns.org/"
step "Sign in. Type a subdomain name and click 'add domain'."
step "Set 'current ip' of the new domain to ${DM_VM_IP} and click 'update ip'."
step "Copy the token at the top of the page."
ask DM_HOST_DUCKDNS_SUBDOMAIN "The subdomain, without .duckdns.org:"
DM_HOST_DUCKDNS_SUBDOMAIN="${DM_HOST_DUCKDNS_SUBDOMAIN%.duckdns.org}"
ask_secret DM_HOST_DUCKDNS_TOKEN "Paste the DuckDNS token (hidden):"
ask DM_HOST_ACME_EMAIL "E-mail for Let's Encrypt certificate notices:"
write_env DM_HOST_DUCKDNS_SUBDOMAIN "$DM_HOST_DUCKDNS_SUBDOMAIN"
write_env DM_HOST_DUCKDNS_TOKEN "$DM_HOST_DUCKDNS_TOKEN"
write_env DM_HOST_ACME_EMAIL "$DM_HOST_ACME_EMAIL"
DM_HOST_URL="https://${DM_HOST_DUCKDNS_SUBDOMAIN}.duckdns.org"
note "The Host URL is ${DM_HOST_URL}."
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Cloudflare Turnstile: the site key and the secret key"
open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
step "Click Add widget. Name: dependency-metrics."
step "Hostname: imranur-rahman.github.io. Widget mode: Managed. Click Create."
step "Copy the Site Key (public) and the Secret Key."
ask DM_TURNSTILE_SITE_KEY "Paste the site key:"
ask_secret DM_HOST_TURNSTILE_SECRET "Paste the secret key (hidden):"
write_env DM_HOST_TURNSTILE_SECRET "$DM_HOST_TURNSTILE_SECRET"
note "The site key goes to a GitHub variable in stage 11, not to host/.env."
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Healthchecks.io: the disk alert at 80%"
say "host/disk-check.sh runs every 15 minutes on the VM and pings this check."
say "At 80% disk use it pings /fail. If the VM stops, the pings stop. Both send an e-mail."
open_url "https://healthchecks.io/"
step "Sign up (free), then click Add Check. Name: dmhost disk."
step "Set Period to 15 minutes and Grace Time to 30 minutes. Save."
step "Copy the ping URL (https://hc-ping.com/...)."
ask DM_HOST_DISK_CHECK_URL "Paste the ping URL:"
write_env DM_HOST_DISK_CHECK_URL "$DM_HOST_DISK_CHECK_URL"
say "host/weekly-maintenance.sh rebuilds the OSV index every 7 days and pings a second check."
step "Click Add Check again. Name: dmhost weekly maintenance."
step "Set Period to 7 days and Grace Time to 1 day. Save. Copy the ping URL."
ask DM_HOST_MAINTENANCE_CHECK_URL "Paste the ping URL:"
write_env DM_HOST_MAINTENANCE_CHECK_URL "$DM_HOST_MAINTENANCE_CHECK_URL"
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "The other values of host/.env"
DM_HOST_IP_HASH_KEY=$(_existing DM_HOST_IP_HASH_KEY || true)
if [[ -z "$DM_HOST_IP_HASH_KEY" ]]; then
  DM_HOST_IP_HASH_KEY=$(openssl rand -hex 32)
  write_env DM_HOST_IP_HASH_KEY "$DM_HOST_IP_HASH_KEY"
else
  note "DM_HOST_IP_HASH_KEY is already set. A new key resets the per-IP limits, so it stays."
fi
write_env DM_HOST_ALLOWED_ORIGINS "$WEBAPP_ORIGIN"
note "The limits and the worker values keep the defaults of host/.env.example."
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "VM: copy host/.env and deploy"
say "This stage copies ${ENV_FILE} to the VM (mode 600) and runs host/deploy.sh there."
say "The first build takes some minutes on the VM."
if confirm "Copy the secrets to the VM and deploy now?"; then
  scp "$ENV_FILE" "${DM_VM_USER}@${DM_VM_IP}:dependency-update-metrics/host/.env"
  ssh "${DM_VM_USER}@${DM_VM_IP}" "chmod 600 dependency-update-metrics/host/.env \
    && bash dependency-update-metrics/host/deploy.sh"
  warn "The secrets must stay only on the VM."
  if confirm "Remove the local copy ${ENV_FILE} now?"; then
    rm -f "$ENV_FILE"
    note "Removed. A new run of the wizard asks for the values again."
  else
    SKIPPED+=("Remove the local secrets file: rm ${ENV_FILE}")
  fi
else
  SKIPPED+=("Copy ${ENV_FILE} to the VM as host/.env and run bash host/deploy.sh there")
fi
pause

# ── 10 ───────────────────────────────────────────────────────────────────
stage "VM: build the OSV index"
say "Without the OSV index every MTTR is 0. The build downloads about 260 MB."
if confirm "Build the OSV index on the VM now?"; then
  ssh "${DM_VM_USER}@${DM_VM_IP}" "cd dependency-update-metrics/host && \
    docker compose run --rm worker dependency-metrics --build-osv --output-dir /data/tool"
else
  SKIPPED+=("OSV index: docker compose run --rm worker dependency-metrics --build-osv --output-dir /data/tool")
fi
say "Check the public health URL:"
if curl -fsS -m 20 "${DM_HOST_URL}/api/health"; then
  printf '\n'
else
  warn "${DM_HOST_URL}/api/health does not answer. Check DNS, ports 80/443, and: docker compose logs caddy"
fi
pause

# ── 11 ───────────────────────────────────────────────────────────────────
stage "GitHub Pages: the Host URL and the Turnstile site key"
say "The Pages workflow puts these two values into the published homepage."
set_var DM_HOST_URL "$DM_HOST_URL"
set_var DM_TURNSTILE_SITE_KEY "$DM_TURNSTILE_SITE_KEY"
note "The workflow publishes only from main, so merge the deploy branch first."
if confirm "Start the Pages workflow on main now?"; then
  gh workflow run webapp.yml --ref main || SKIPPED+=("Start the 'Webapp CI and Pages' workflow on main")
else
  SKIPPED+=("Start the 'Webapp CI and Pages' workflow on main")
fi
open_url "https://imranur-rahman.github.io/dependency-update-metrics/#try-it"
step "When the workflow is done, run one full Comparison from the public homepage."
pause "Press Enter when the Comparison shows its results."

# ── 12 ───────────────────────────────────────────────────────────────────
stage "UptimeRobot: the uptime monitor"
say "A monitor tells you by e-mail when the Host stops answering."
open_url "https://dashboard.uptimerobot.com/"
step "Sign up (free) and click New monitor."
step "Type: HTTP(s). URL: ${DM_HOST_URL}/api/health. Interval: 5 minutes."
step "Alert contact: your e-mail. Click Create monitor."
step "Check that the monitor shows Up."
pause "Press Enter when the monitor is Up."

finish
note "host/RUNBOOK.md has the steps for later deploys."
}

run_wizard "$@"; exit
